1	// 🟢 📜 A.N.N.A. Scribe (Axon Network Notary Arbitrator)
2	// The top-level Identity-State Arbitrator who notarizes WireGuard identity
3	// against the 1:1 IdentitySled in shared memory and handles the "Snowball" session.
4	
5	use chrono::Utc;
6	use memmap2::MmapOptions;
7	use std::fs::{File, OpenOptions};
8	use std::io::Write;
9	
10	use crate::IdentitySled;
11	
12	/// The genesis "Snowball" session record, created by A.N.N.A. Scribe when a WireGuard
13	/// connection arrives. This is the first entry in the accountability loop, tying the
14	/// WireGuard pubkey to the current schema mutation state.
15	#[derive(Debug)]
16	pub struct SessionLedger {
17	    pub wireguard_pubkey: String,
18	    pub hashed_footprint: String, // The genesis "Snowball"
19	    pub trace_id: String,
20	}
21	
22	/// A.N.N.A. Scribe (Axon Network Notary Arbitrator)
23	///
24	/// The top-level gatekeeper who merges the ephemeral WireGuard identity with the
25	/// absolute present state into a "Snowball" session. She relies strictly on the
26	/// 1:1 `IdentitySled`. If the schema footprint in memory is invalid (all zeros),
27	/// she refuses to generate the session identity — enforcing that without a valid
28	/// schema, the entity does not exist on the system.
29	pub struct AnnaScribe;
30	
31	/// Check whether a sled is "valid" per the Absolute Base rule.
32	fn is_sled_valid(sled: &IdentitySled) -> bool {
33	    // A valid sled must have a non-zero footprint and trace_id.
34	    sled.hashed_footprint != [0u8; 32] && sled.trace_id != [0u8; 16]
35	}
36	
37	impl AnnaScribe {
38	    /// THE GREETING (Genesis Call)
39	    ///
40	    /// A.N.N.A. Scribe notarizes the WireGuard identity against the 1:1 memory sled.
41	    /// She casts a raw pointer to the `IdentitySled` in shared memory, extracts the
42	    /// `mutation_index`, and performs the **Strike/Etch** to generate the first hashed
43	    /// footprint. This creates the **Snowball** session ledger entry entirely in memory,
44	    /// completely avoiding unintended Btrfs mutation loops while preserving NVMe I/O
45	    /// strictly for the blockchain transport.
46	    ///
47	    /// Uses Blake3 per the spec for all Strike/Etch operations.
48	    pub fn notarize_arrival(wg_pubkey: &str) -> Result<SessionLedger, String> {
49	        // 1:1 Direct Read from the SchemaEngine's shared memory (No SQL, No Polling)
50	        let file = File::open("/dev/shm/plugin_schema.dat")
51	            .map_err(|_| "A.N.N.A. Scribe: Missing Schema. Connection Rejected.".to_string())?;
52	
53	        let mmap = unsafe {
54	            MmapOptions::new()
55	                .map(&file)
56	                .map_err(|_| "Memory map failed".to_string())?
57	        };
58	        let sled_ptr = mmap.as_ptr() as *const IdentitySled;
59	        let sled = unsafe { &*sled_ptr };
60	
61	        // The Absolute Base: No valid schema, does not exist.
62	        if !is_sled_valid(sled) {
63	            return Err("A.N.N.A. Scribe: Invalid Schema State. Cease and Desist.".to_string());
64	        }
65	
66	        // The Strike/Etch: Bind the WireGuard Key to the Blake3 hash of the
67	        // canonical schema catalog in shared memory. This makes the sled footprint
68	        // a direct function of the single source of truth (/dev/shm/live-schema.json).
69	        let schema_catalog_hash = crate::schema_bridge::schema_catalog_hash().ok_or_else(|| {
70	            "A.N.N.A. Scribe: Schema catalog missing from shared memory. Connection Rejected."
71	                .to_string()
72	        })?;
73	
74	        let mut hasher = blake3::Hasher::new();
75	        hasher.update(wg_pubkey.as_bytes());
76	        hasher.update(&schema_catalog_hash);
77	        hasher.update(&sled.mutation_index.to_le_bytes());
78	        let genesis_hash = hex::encode(hasher.finalize().as_bytes());
79	
80	        Ok(SessionLedger {
81	            wireguard_pubkey: wg_pubkey.to_string(),
82	            hashed_footprint: genesis_hash.clone(),
83	            trace_id: format!("trace-{}", genesis_hash),
84	        })
85	    }
86	
87	    /// THE STRIKE/ETCH: Generates the cryptographic hash (footprint) for the identity.
88	    /// Binds the WireGuard public key to the Blake3 hash of the canonical schema catalog
89	    /// in shared memory (/dev/shm/live-schema.json), plus the mutation index.
90	    /// This makes the sled footprint a direct function of the single source of truth.
91	    pub fn etch_footprint(sled: &IdentitySled, source_port: u16) -> [u8; 32] {
92	        // Single source of truth: delegate to the canonical Strike/Etch.
93	        crate::schema_bridge::etch_footprint(
94	            &sled.wireguard_pubkey,
95	            sled.mutation_index,
96	            source_port,
97	        )
98	    }
99	
100	    /// THE SNOWBALL: Appends the session ledger.
101	    /// Strictly preserved in RAM (tmpfs) to avoid Btrfs mutation loops.
102	    /// NVMe I/O is preserved strictly for the Btrfs vectorized footprint transport.
103	    pub fn append_snowball(footprint: &[u8; 32], action: &str) -> anyhow::Result<()> {
104	        let timestamp = Utc::now().to_rfc3339();
105	        let footprint_hex = hex::encode(footprint);
106	        let entry = format!("[{}] {} | {}\n", timestamp, footprint_hex, action);
107	
108	        // Path is in tmpfs to preserve NVMe I/O for Btrfs blockchain transport
109	        let snowball_path = "/dev/shm/snowball_session.log";
110	
111	        let mut file = OpenOptions::new()
112	            .create(true)
113	            .append(true)
114	            .open(snowball_path)?;
115	
116	        file.write_all(entry.as_bytes())?;
117	        Ok(())
118	    }
119	}
120	
121	#[cfg(test)]
122	mod tests {
123	    use super::*;
124	
125	    #[test]
126	    fn test_notarize_arrival_requires_schema_catalog() {
127	        // This test verifies that notarize_arrival checks for schema catalog.
128	        // When schema catalog is missing, it should return an error.
129	        // Note: current sled may be valid, but catalog may be missing.
130	        let result = AnnaScribe::notarize_arrival("test-pubkey-abc");
131	        // Either we get an error (no catalog) or success (catalog exists)
132	        // Just verify the function handles both cases gracefully.
133	        match result {
134	            Ok(ledger) => {
135	                // Schema catalog exists - verify ledger is well-formed
136	                assert!(!ledger.hashed_footprint.is_empty());
137	            }
138	            Err(e) => {
139	                // Schema catalog missing - verify error message
140	                assert!(e.contains("Schema") || e.contains("schema"));
141	            }
142	        }
143	    }
144	
145	    #[test]
146	    fn test_notarize_arrival_rejects_invalid_sled() {
147	        let sled = IdentitySled {
148	            wireguard_pubkey: [0u8; 32],
149	            mutation_index: 1,
150	            hashed_footprint: [0u8; 32],
151	            trace_id: [0u8; 16],
152	            vector_id: [0u8; 16],
153	            schema_version: 0,
154	            reserved: [0u8; 44],
155	        };
156	        assert!(!is_sled_valid(&sled));
157	    }
158	
