175	        let mut h1 = blake3::Hasher::new();
176	        h1.update(b"wg-pubkey-abc123");
177	        h1.update(&42u64.to_le_bytes());
178	        let hash1 = hex::encode(h1.finalize().as_bytes());
179	
180	        let mut h2 = blake3::Hasher::new();
181	        h2.update(b"wg-pubkey-abc123");
