209	        let mut ha = blake3::Hasher::new();
210	        ha.update(b"wg-pubkey-aaa");
211	        ha.update(&1u64.to_le_bytes());
212	        let hash_a = hex::encode(ha.finalize().as_bytes());
213	
214	        let mut hb = blake3::Hasher::new();
215	        hb.update(b"wg-pubkey-bbb");
