//! EMQX HookProvider gRPC service implementation.
//!
//! EMQX acts as a gRPC client, calling this service for MQTT events.
//! The implementation records events through MutationEngine for accountability.

use tonic::{Request, Response, Status};
use tracing::{debug, info};

use crate::mutation_engine::MutationEngine;

/// HookProvider service implementation for EMQX MQTT event hooks.
///
/// All EMQX hook events are recorded as signals through the MutationEngine,
/// providing accountability and persistence without direct SQL storage.
#[derive(Clone)]
pub struct HookProviderService {
    mutation_engine: std::sync::Arc<MutationEngine>,
}

impl HookProviderService {
    pub fn new(mutation_engine: std::sync::Arc<MutationEngine>) -> Self {
        Self { mutation_engine }
    }

    /// Record an EMQX event as a signal mutation.
    async fn record_event(
        &self,
        event_type: &str,
        client_id: &str,
        topic: Option<&str>,
        payload: Option<&str>,
    ) -> anyhow::Result<()> {
        let mut event_data = simd_json::json!({
            "event_type": event_type,
            "client_id": client_id,
        });

        if let Some(t) = topic {
            event_data["topic"] = simd_json::json!(t);
        }
        if let Some(p) = payload {
            event_data["payload"] = simd_json::json!(p);
        }

        self.mutation_engine
            .dispatch_method_call(
                "mqtt",
                &format!("hook.{}", event_type),
                &serde_json::to_string(&event_data)?,
                None,
                "grpc:emqx.exhook.v1",
            )
            .await?;

        Ok(())
    }
}

#[tonic::async_trait]
impl crate::proto::emqx_exhook::hook_provider_server::HookProvider for HookProviderService {
    async fn on_client_connect(
        &self,
        request: Request<crate::proto::emqx_exhook::OnClientConnectRequest>,
    ) -> Result<Response<crate::proto::emqx_exhook::OnClientConnectResponse>, Status> {
        let req = request.into_inner();
        let client = req
            .client
            .as_ref()
            .map(|c| c.clientid.as_str())
            .unwrap_or("unknown");

        debug!(client_id = %client, proto = %req.proto, "EMQX OnClientConnect");
        let _ = self
            .record_event("on_client_connect", client, None, None)
            .await;

        Ok(Response::new(
            crate::proto::emqx_exhook::OnClientConnectResponse {
                success: true,
                error: String::new(),

